import {poseAt,poseDefaults,identity,skinMatrices,skinPoint} from './rig.js';
// glTF 2.0: Y-up metres, inverse bind matrices, four normalized skin weights,
// relative POSITION morphs and sampled quaternion/weight animation channels.
export function toGLB(mesh,pose=poseDefaults){
 if(!mesh.parts||!mesh.rig)throw Error('GLBは実データ方式で書き出せます。');
 const doc={asset:{version:'2.0',generator:'FORM Character Studio 0.3',copyright:'Base body: MakeHuman CC0. Procedural hair and rig: FORM.'},scene:0,scenes:[{name:'FORM Character',nodes:[0]}],nodes:[{name:'Character',children:[1]}],meshes:[],skins:[],materials:[],buffers:[],bufferViews:[],accessors:[],animations:[]},chunks=[];let offset=0;
 const add=(typed,type,componentType,target,bounds=false)=>{const padding=(4-offset%4)%4;if(padding){chunks.push(new Uint8Array(padding));offset+=padding;}const view=doc.bufferViews.length,bytes=new Uint8Array(typed.buffer,typed.byteOffset,typed.byteLength);chunks.push(bytes);doc.bufferViews.push({buffer:0,byteOffset:offset,byteLength:bytes.length,...(target?{target}:{})});offset+=bytes.length;const width={SCALAR:1,VEC3:3,VEC4:4,MAT4:16}[type],a={bufferView:view,componentType,count:typed.length/width,type};if(bounds){a.min=Array(width).fill(Infinity);a.max=Array(width).fill(-Infinity);for(let i=0;i<typed.length;i++){a.min[i%width]=Math.min(a.min[i%width],typed[i]);a.max[i%width]=Math.max(a.max[i%width],typed[i]);}}doc.accessors.push(a);return doc.accessors.length-1;};
 const staticSample=poseAt(pose,'none',0,[mesh.studio.blink,mesh.studio.smile,mesh.studio.mouthOpen]);
 mesh.rig.forEach((b,i)=>{doc.nodes.push({name:b.name,translation:b.position.map((x,k)=>x-(b.parent<0?0:mesh.rig[b.parent].position[k])),rotation:staticSample.rotations[i]});if(b.parent>=0)(doc.nodes[b.parent+1].children??=[]).push(i+1);});
 const inverses=new Float32Array(mesh.rig.length*16);mesh.rig.forEach((b,i)=>{const m=identity();for(let k=0;k<3;k++)m[12+k]=-b.position[k];inverses.set(m,i*16);});doc.skins.push({name:'FORM Biped',skeleton:1,joints:mesh.rig.map((_,i)=>i+1),inverseBindMatrices:add(inverses,'MAT4',5126)});
 const meshNodes=[];for(const part of mesh.parts){const attributes={POSITION:add(part.vertices,'VEC3',5126,34962,true),NORMAL:add(part.normals,'VEC3',5126,34962),COLOR_0:add(part.colors,'VEC3',5126,34962),JOINTS_0:add(part.joints,'VEC4',5123,34962),WEIGHTS_0:add(part.weights,'VEC4',5126,34962)},targets=['blink','smile','mouth'].map(k=>({POSITION:add(part[k],'VEC3',5126,34962,true)}));
 doc.materials.push({name:part.name+' Material',doubleSided:true,pbrMetallicRoughness:{baseColorFactor:[1,1,1,1],metallicFactor:0,roughnessFactor:part.roughness}});
 const index=doc.meshes.length;doc.meshes.push({name:part.name,weights:staticSample.expression,extras:{targetNames:['Blink','Smile','MouthOpen'],part:part.group},primitives:[{attributes,indices:add(part.indices,'SCALAR',5125,34963),material:index,targets}]});const n=doc.nodes.length;doc.nodes.push({name:part.name,mesh:index,skin:0});doc.nodes[0].children.push(n);meshNodes.push(n);}
 const times=new Float32Array(Array.from({length:73},(_,i)=>i/24)),timeAccessor=add(times,'SCALAR',5126,undefined,true);
 for(const [name,clip]of [['Greeting','greeting'],['FaceStudy','expression']]){const animation={name,channels:[],samplers:[]},samples=Array.from(times,t=>poseAt(poseDefaults,clip,t));const channel=(values,type,node,path)=>{const index=animation.samplers.length;animation.samplers.push({input:timeAccessor,output:add(new Float32Array(values),type,5126),interpolation:'LINEAR'});animation.channels.push({sampler:index,target:{node,path}});};for(let i=0;i<mesh.rig.length;i++)channel(samples.flatMap(x=>x.rotations[i]),'VEC4',i+1,'rotation');for(const n of meshNodes)channel(samples.flatMap(x=>x.expression),'SCALAR',n,'weights');doc.animations.push(animation);}
 const pad=(4-offset%4)%4;if(pad){chunks.push(new Uint8Array(pad));offset+=pad;}doc.buffers=[{byteLength:offset}];const json=new TextEncoder().encode(JSON.stringify(doc)),jsonLength=Math.ceil(json.length/4)*4,total=12+8+jsonLength+8+offset,buffer=new ArrayBuffer(total),bytes=new Uint8Array(buffer),view=new DataView(buffer);view.setUint32(0,0x46546c67,true);view.setUint32(4,2,true);view.setUint32(8,total,true);view.setUint32(12,jsonLength,true);view.setUint32(16,0x4e4f534a,true);bytes.fill(32,20,20+jsonLength);bytes.set(json,20);view.setUint32(20+jsonLength,offset,true);view.setUint32(24+jsonLength,0x004e4942,true);let cursor=28+jsonLength;for(const chunk of chunks){bytes.set(chunk,cursor);cursor+=chunk.length;}return buffer;
}
export function characterOBJ(mesh,pose,expression,rotations){const sample=poseAt(pose,'none',0,expression),matrices=skinMatrices(mesh.rig,rotations||sample.rotations),rows=['# FORM assembled character, current pose; unit metre'];let offset=1;for(const p of mesh.parts){rows.push('o '+p.name);for(let i=0;i<p.vertices.length/3;i++){const v=[0,1,2].map(k=>p.vertices[i*3+k]+p.blink[i*3+k]*expression[0]+p.smile[i*3+k]*expression[1]+p.mouth[i*3+k]*expression[2]);const xyz=skinPoint(v,p.joints.slice(i*4,i*4+4),p.weights.slice(i*4,i*4+4),matrices);rows.push('v '+xyz.map(v=>v.toFixed(6)).join(' '));}for(let i=0;i<p.indices.length;i+=3)rows.push('f '+[0,1,2].map(k=>p.indices[i+k]+offset).join(' '));offset+=p.vertices.length/3;}return rows.join('\n');}
